// Own: zzOWN.com - Own Fast. Work Faster.  | Ema: zzown.com@gmail.com
// Des: Dispatch a command to its code: status, jobs, run, ask, flows, map, doctor, snap, support tools
// Flo: command word > browser needed? > run the matching module > print result lines (or JSON)
// I/O: Ctx + Args (caller) > exit code 0; typed errors for the caller to print
// ===================================================================
const std = @import("std"); const task = @import("ru-task-runn.zig"); const targ = @import("ct-ctrl-args.zig"); const pace = @import("ru-huma-pace.zig"); const disp = @import("ru-jobs-disp.zig"); const reci = @import("ru-reci-main.zig"); const queu = @import("ru-flow-queu.zig"); const appr = @import("ru-appr-list.zig"); const wait = @import("ru-wait-hand.zig"); const doct = @import("ru-doct-main.zig"); const snap = @import("ru-snap-main.zig"); const setu = @import("ct-comm-setu.zig"); const misc = @import("ct-comm-misc.zig"); const mapz = @import("ru-page-mapz.zig");
const KINDS = [_]pace.Kind{ .acct, .prod, .data, .mone, .acce, .sett, .help };
const CF = .{ .dayz = 86400000, .nlog = 20 };
pub fn needBrow(args: targ.Args) bool { const cmd = args.cmdz; const names = [_][]const u8{ "login", "setup", "doctor", "snap", "map" }; for (names) |nam| if (std.mem.eql(u8, nam, cmd)) return true; if (std.mem.eql(u8, cmd, "run") or std.mem.eql(u8, cmd, "ask")) return args.live; return std.mem.eql(u8, cmd, "flow") and std.mem.eql(u8, args.subz, "run") and args.live; }
const CapRow = struct { kind: []const u8, used: i64, cap: u32 };
const FlowRow = struct { id: i64, name: []const u8, state: []const u8, interventions: i64, wait_secs: i64 };
const Stz = struct { app: []const u8, version: []const u8, paused: bool, consent: bool, cool: bool, unsafe_until: i64, warm_perc: u32, quiet_now: bool, last_halt: []const u8, flow: ?FlowRow, caps: []const CapRow };
fn capRows(ctx: *task.Ctx) ![]const CapRow { const now = task.nowMs(ctx); const born = try ctx.store.bornGet(now); var perc = pace.warmPerc(born, now, ctx.conf.warm_dayz_coun); if (task.coolOn(ctx)) perc = perc * ctx.conf.cool_perc_caps / 100; var out: std.ArrayList(CapRow) = .empty; for (KINDS) |kin| try out.append(ctx.aren, .{ .kind = @tagName(kin), .used = try ctx.store.actCnt(@tagName(kin), now - CF.dayz), .cap = pace.capEff(pace.capOf(ctx.conf, kin), perc) }); return out.items; }
fn lastHalt(ctx: *task.Ctx) ![]const u8 { const rows = try ctx.store.logRecent(ctx.aren, 200); for (rows) |row| { if (std.mem.eql(u8, row.kind, "halt")) return row.what; } return ""; }
fn flowRow(ctx: *task.Ctx) !?FlowRow { const fid = try ctx.store.flowLast(); if (fid == 0) return null; const fl = (try ctx.store.flowGet(ctx.aren, fid)) orelse return null; return .{ .id = fl.id, .name = fl.name, .state = fl.st, .interventions = fl.ivn, .wait_secs = @divFloor(fl.wms, 1000) }; }
fn statusRun(ctx: *task.Ctx, args: targ.Args) !void { const now = task.nowMs(ctx); const born = try ctx.store.bornGet(now); const stz: Stz = .{ .app = "zr", .version = misc.VERS, .paused = try ctx.store.flagGet("pause"), .consent = task.consentOk(ctx), .cool = task.coolOn(ctx), .unsafe_until = wait.unsafeUntil(ctx), .warm_perc = pace.warmPerc(born, now, ctx.conf.warm_dayz_coun), .quiet_now = pace.quietNow(now, ctx.conf.quie_zone_minu, ctx.conf.quie_hour_rang), .last_halt = try lastHalt(ctx), .flow = try flowRow(ctx), .caps = try capRows(ctx) }; if (args.json) { task.say(ctx, "{s}", .{try std.json.Stringify.valueAlloc(ctx.aren, stz, .{})}); return; } task.say(ctx, "zr {s} status: paused={any} consent={any} cool-pace={any} warm-up={d}% quiet-now={any} last-halt={s}", .{ stz.version, stz.paused, stz.consent, stz.cool, stz.warm_perc, stz.quiet_now, if (stz.last_halt.len > 0) stz.last_halt else "none" }); if (stz.unsafe_until > wait.realMs(ctx.iozz)) task.say(ctx, "  safety rest until {d} (run: zr resume to override)", .{stz.unsafe_until}); if (stz.flow) |fl| task.say(ctx, "  last flow {d} \"{s}\": {s}, interventions {d}, waited {d} s", .{ fl.id, fl.name, fl.state, fl.interventions, fl.wait_secs }); for (stz.caps) |row| task.say(ctx, "  {s}: {d}/{d} in the last 24h", .{ row.kind, row.used, row.cap }); }
fn logRun(ctx: *task.Ctx, args: targ.Args) !void { const rows = try ctx.store.logRecent(ctx.aren, CF.nlog); if (args.json) { task.say(ctx, "{s}", .{try std.json.Stringify.valueAlloc(ctx.aren, rows, .{})}); return; } if (rows.len == 0) { task.say(ctx, "log is empty", .{}); return; } for (rows) |row| task.say(ctx, "{d} {s} {s} {s}", .{ row.ts, if (row.ok) "ok  " else "FAIL", row.kind, row.what }); }
fn jobsRun(ctx: *task.Ctx) void { var ix: usize = 0; while (ix < disp.rowCount()) : (ix += 1) { const rw = disp.rowAt(ix); task.say(ctx, "{s:<16} {s}  cap:{s}  {s}", .{ rw.name, if (rw.risk == 'x') "X (needs OK)" else "W", rw.kind, rw.hint }); } for (ctx.conf.flow_list) |fl| task.say(ctx, "routine {s}: {d} jobs", .{ fl.name, fl.jobs.len }); }
fn askRun(ctx: *task.Ctx, text: []const u8, base: task.Args) !void { const cmd = (try reci.parse(ctx.aren, text)) orelse { task.say(ctx, "I did not understand. Try: get <url> as text | sign up | log in | show usage | create key <name> | docs <words>", .{}); return error.BadUsage; }; var tsk = cmd.args; tsk.maxn = base.maxn; task.say(ctx, "understood: {s}", .{cmd.job}); try disp.exec(ctx, cmd.job, tsk); }
fn lastFlow(ctx: *task.Ctx) !i64 { const open = try ctx.store.flowOpen(); if (open != 0) return open; return ctx.store.flowLast(); }
fn planRun(ctx: *task.Ctx, args: targ.Args) !void { const fid = if (args.subz.len > 0) try queu.openOrNew(ctx, args.subz) else try lastFlow(ctx); if (fid == 0) { task.say(ctx, "no plan yet: run: zr plan <routine>", .{}); return; } _ = try appr.show(ctx, fid); }
fn approveRun(ctx: *task.Ctx, args: targ.Args, val: i64) !void { if (args.subz.len == 0) return error.BadUsage; const fid = try lastFlow(ctx); if (fid == 0) return error.BadFlow; const cnt = try appr.setAppr(ctx, fid, args.subz, val); task.say(ctx, "{s}: {d} item(s)", .{ if (val == 1) "approved" else "denied", cnt }); }
fn flowCmd(ctx: *task.Ctx, args: targ.Args) !void { if (std.mem.eql(u8, args.subz, "list")) { jobsRun(ctx); return; } if (std.mem.eql(u8, args.subz, "show")) { const fid = try ctx.store.flowLast(); if (fid == 0) return error.BadFlow; try queu.summary(ctx, fid); return; } if (std.mem.eql(u8, args.subz, "run")) { if (args.extr.len == 0) return error.BadUsage; const fid = try queu.openOrNew(ctx, args.extr); const res = try queu.runFlow(ctx, fid); task.say(ctx, "flow {d}: {s} · {d} done · {d} skipped · {d} failed · {d} unsure", .{ fid, res.state, res.done, res.skip, res.fail, res.unsure }); if (std.mem.eql(u8, res.state, "stop")) return error.Unsafe; if (std.mem.eql(u8, res.state, "park")) return error.WaitTimeout; return; } return error.BadUsage; }
fn resumeRun(ctx: *task.Ctx) !void { try ctx.store.flagSet("pause", false); try ctx.store.metaSet("unsafe_until", 0); task.say(ctx, "resumed (pause and safety rest cleared)", .{}); }
pub fn dispatch(ctx: *task.Ctx, args: targ.Args) !u8 { const cmd = args.cmdz; if (std.mem.eql(u8, cmd, "status") or std.mem.eql(u8, cmd, "caps")) { try statusRun(ctx, args); } else if (std.mem.eql(u8, cmd, "log")) { try logRun(ctx, args); } else if (std.mem.eql(u8, cmd, "jobs")) { jobsRun(ctx); } else if (std.mem.eql(u8, cmd, "pause")) { try ctx.store.flagSet("pause", true); task.say(ctx, "paused: running jobs stop at the next step", .{}); } else if (std.mem.eql(u8, cmd, "resume")) { try resumeRun(ctx); } else if (std.mem.eql(u8, cmd, "unlock")) { if (args.subz.len == 0) return error.BadUsage; try ctx.store.keyDrop(args.subz); task.say(ctx, "unlocked: {s}", .{args.subz}); } else if (std.mem.eql(u8, cmd, "plan")) { try planRun(ctx, args); } else if (std.mem.eql(u8, cmd, "approve")) { try approveRun(ctx, args, 1); } else if (std.mem.eql(u8, cmd, "deny")) { try approveRun(ctx, args, 2); } else if (std.mem.eql(u8, cmd, "flow")) { try flowCmd(ctx, args); } else if (std.mem.eql(u8, cmd, "login")) { try setu.loginRun(ctx); } else if (std.mem.eql(u8, cmd, "setup")) { try setu.setupRun(ctx, args.yesz, ctx.grant, ctx.dataroot); } else if (std.mem.eql(u8, cmd, "doctor")) { _ = try doct.doctor(ctx, args.subz, args.tsk.url); } else if (std.mem.eql(u8, cmd, "map")) { _ = try mapz.mapRun(ctx); } else if (std.mem.eql(u8, cmd, "snap")) { if (args.subz.len == 0) return error.BadUsage; _ = try snap.capture(ctx, args.subz, if (args.extr.len > 0) args.extr else "page"); } else if (std.mem.eql(u8, cmd, "report")) { _ = try misc.report(ctx); } else if (std.mem.eql(u8, cmd, "backup")) { _ = try misc.backup(ctx); } else if (std.mem.eql(u8, cmd, "export")) { _ = try misc.exportData(ctx); } else if (std.mem.eql(u8, cmd, "purge")) { _ = try misc.purgeRun(ctx); } else if (std.mem.eql(u8, cmd, "run")) { if (args.subz.len == 0) return error.BadUsage; try disp.exec(ctx, args.subz, args.tsk); } else if (std.mem.eql(u8, cmd, "ask")) { if (args.subz.len == 0) return error.BadUsage; try askRun(ctx, args.subz, args.tsk); } else return error.BadUsage; return 0; }
